Lemma norm_spec r t nb :
  1 <= r -> 1 <= nb -> t = 2^(nb-1) -> r < 2*t ->
  let '(t', nb') := norm r t nb in
  t' = 2^(nb'-1) /\ 1 <= nb' <= nb /\ t' <= r < 2*t'.
