  Lemma astep_ainv a :
    ainv a -> a_sym a <= maxSV ->
    ainv (astep a) /\ a_sym a < a_sym (astep a) /\
    a_T a < a_T (astep a) /\ a_N (astep a) mod 2^(a_T a) = a_N a.
